-- Up Migration
--
-- Staff accounts, plus a matching auto-generated email for learners. Both
-- emails follow the same convention: first initial + surname @ the school's
-- own id, e.g. "jdoe@sch1.school" — generated by the application (see
-- lib/identity/email.ts), not by the database.

CREATE TABLE employees (
    employee_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    school_id CHAR(4) NOT NULL,
    first_name VARCHAR(100) NOT NULL,
    last_name VARCHAR(100) NOT NULL,
    role VARCHAR(100) NOT NULL,
    email VARCHAR(255) NOT NULL,
    -- Self-describing (algorithm + params + salt + hash) so the scheme can
    -- change later without invalidating rows already issued — see
    -- lib/auth/password.ts.
    password_hash TEXT NOT NULL,
    must_change_password BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_employee_school
        FOREIGN KEY (school_id)
        REFERENCES schools(school_id)
        ON DELETE CASCADE,

    CONSTRAINT uq_employee_email
        UNIQUE (school_id, email)
);

-- Nullable: existing learners keep no email until they're next edited, and
-- new ones get one generated at creation time (repositories/learner/create).
ALTER TABLE learners ADD COLUMN email VARCHAR(255);

ALTER TABLE learners ADD CONSTRAINT uq_learner_email UNIQUE (school_id, email);

-- Down Migration

ALTER TABLE learners DROP CONSTRAINT IF EXISTS uq_learner_email;
ALTER TABLE learners DROP COLUMN IF EXISTS email;
DROP TABLE IF EXISTS employees;
